+	if (map) {
+		map->remove_agent(this);
+	}
+
+	map = p_map;
+	agent_dirty = true;
+
+	if (map) {
+		map->add_agent(this);
+		if (avoidance_enabled) {
+			map->set_agent_as_controlled(this);
+		}
+
+		request_sync();
+	}
+}
