+bool NavAgent2D::is_map_changed() {
+	if (map) {
+		bool is_changed = map->get_iteration_id() != last_map_iteration_id;
+		last_map_iteration_id = map->get_iteration_id();
+		return is_changed;
+	} else {
+		return false;
